import type { LifecycleDefinition } from './lifecycle-definition-model';
import type { Workspace } from './workspace-model';

export const LifecycleStatusStatusKeyToLabel = {
  'Active': 'Active',
  'Inactive': 'Inactive'
} as const;
export type LifecycleStatusStatusKey = keyof typeof LifecycleStatusStatusKeyToLabel;

export interface LifecycleStatus {
  /**
   * @displayName Lifecycle Status ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Status Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  statusName: string;
  /**
   * @displayName Lifecycle
   * @validationRule Required for create/update operations
   */
  lifecycle: Pick<LifecycleDefinition, 'id' | 'name1'>;
  /**
   * @displayName Pause Targets
   * @validationRule Required for create/update operations
   */
  pauseTargets: boolean;
  /**
   * @displayName Sort Order
   * @validationRule Required for create/update operations
   */
  sortOrder: number;
  /**
   * @displayName Stage Code
   * @validationRule Required for create/update operations
   */
  stageCode: string;
  /**
   * @displayName Status Code
   * @validationRule Required for create/update operations
   */
  statusCode: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: LifecycleStatusStatusKey;
  /**
   * @displayName Terminal
   * @validationRule Required for create/update operations
   */
  terminal: boolean;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _LifecycleStatus = 'LifecycleStatus' as const;